@media(max-width:950px){.style-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:650px){.style-hero{display:grid;padding:21px 17px}.style-hero h1{font-size:27px}.style-grid{grid-template-columns:1fr}.style-labels small{width:100%;margin-left:0}.percentile-row{grid-template-columns:1fr}.percentile-row b{text-align:left}.rotation-grid{grid-template-columns:1fr}}
